import java.util.Iterator;
import java.util.List;

public class MyLadder implements ILadder {

    private int countLetters(String s) {
        if (s == null) {
            return 0;
        }
        int cnt = 0;
        for (int i = 0; i < s.length(); i++) {
            if (Character.isLetter(s.charAt(i))) {
                cnt++;
            }
        }
        return cnt;
    }

    @Override
    public int f1(List<Ladder> t) {
        if (t == null) {
            return 0;
        }
        int sum = 0;
        for (Ladder l : t) {
            if (l == null || l.getType() == null) {
                continue;
            }
            int upper = 0;
            int lower = 0;
            String s = l.getType();
            for (int i = 0; i < s.length(); i++) {
                char c = s.charAt(i);
                if (c >= 'A' && c <= 'Z') {
                    upper++;
                } else if (c >= 'a' && c <= 'z') {
                    lower++;
                }
            }
            if (upper > lower) {
                sum += l.getPrice();
            }
        }
        return sum;
    }

    @Override
    public void f2(List<Ladder> t) {
        if (t == null || t.isEmpty()) {
            return;
        }
        int maxLen = 0;
        for (Ladder l : t) {
            if (l != null && l.getType() != null && l.getType().length() > maxLen) {
                maxLen = l.getType().length();
            }
        }
        for (Ladder l : t) {
            if (l != null && l.getType() != null && l.getType().length() == maxLen) {
                l.setPrice(0);
            }
        }
    }

    @Override
    public void f3(List<Ladder> t) {
        if (t == null || t.isEmpty()) {
            return;
        }
        int maxLetters = -1;
        for (Ladder l : t) {
            if (l != null) {
                int cnt = countLetters(l.getType());
                if (cnt > maxLetters) {
                    maxLetters = cnt;
                }
            }
        }
        Iterator<Ladder> it = t.iterator();
        while (it.hasNext()) {
            Ladder l = it.next();
            if (l != null && countLetters(l.getType()) == maxLetters) {
                it.remove();
            }
        }
    }
}

